  $swpsjson${"slug": "social-welfare-policy-and-services", "title": "Social Welfare Policy and Services", "description": "Introduce social welfare as a set of public choices about need, rights, risk, responsibility, and collective well-being. Students trace U.S. welfare history and competing ideas about deservingness, markets, family, government, work, citizenship, and social rights, then study poverty, major programs, cash assistance, aging and disability, health, food, housing, and child welfare policy. The course builds tools for equity analysis, advocacy, implementation, administrative burden, and evaluation.", "topics": [{"id": "db67e3c8-a9b3-497e-a3e1-b84295272f08", "type": "topic", "title": "Social Welfare Policy and Services Foundations", "description": "Introduce social welfare as a set of public choices about need, rights, risk, responsibility, and collective well-being.", "children": [{"id": "4a35bdba-42b2-4c13-b4c9-a4c9cc24aaeb", "type": "subtopic", "title": "What Counts as Social Welfare", "children": [{"id": "b89faef7-764f-49ae-93ff-629f273e6491", "type": "concept", "title": "Social insurance"}, {"id": "e23a5b7d-d4b9-43c4-a047-631a4ce9be34", "type": "concept", "title": "Public assistance"}, {"id": "1e23cf18-d848-4cc0-af9a-ebfc4f3afd8e", "type": "concept", "title": "Social services"}, {"id": "d02bb977-1834-4f44-bfef-84a2f7e092d4", "type": "concept", "title": "Tax benefits and hidden welfare state"}], "description": "This subtopic defines the course terrain and helps students see social welfare beyond a narrow idea of welfare checks."}, {"id": "54deb675-6032-42b2-8c7d-c0f36a6e7010", "type": "subtopic", "title": "Policy, Services, and Practice", "children": [{"id": "704c67da-1a64-4ce6-ba02-0fc17a085b0e", "type": "concept", "title": "Eligibility"}, {"id": "47cb5cfd-5904-4c7e-89d2-12cc361fb2f6", "type": "concept", "title": "Benefits and sanctions"}, {"id": "95612121-4098-4a54-bb0e-ac6b3dc500ca", "type": "concept", "title": "Casework and administration"}, {"id": "584a9cda-cacc-4517-b8b6-3cd494491a03", "type": "concept", "title": "Policy-practice feedback loops"}], "description": "Students learn why policy and service delivery are inseparable in social work and human services."}, {"id": "4bd5ece1-49fd-4b93-b935-682fe29ccab2", "type": "subtopic", "title": "Core Values and Tensions", "children": [{"id": "3684a495-1564-40a1-a6a2-69338b01836c", "type": "concept", "title": "Need and rights"}, {"id": "072bb598-de3d-4fcc-b1b0-cd406a3318c0", "type": "concept", "title": "Equity and efficiency"}, {"id": "0698ae22-e5fd-433d-b88a-2d22e90672e7", "type": "concept", "title": "Care and control"}, {"id": "4295cfe4-2bfb-4923-9302-b785dfe55436", "type": "concept", "title": "Universalism and selectivity"}], "description": "Social welfare debates are shaped by values that often conflict in real policy choices."}]}, {"id": "acec4e18-d4a4-47a4-89cb-5ae76202bbf8", "type": "topic", "title": "History of U.S. Social Welfare", "description": "Trace how social welfare institutions developed through charity, settlement work, the New Deal, civil rights, welfare reform, and contemporary debates.", "children": [{"id": "64ce2bf3-ccf2-4aed-979e-c8afc60de710", "type": "subtopic", "title": "Poor Relief and Charity Traditions", "children": [{"id": "3a5d6af7-c368-4d21-9962-7e5224c1932a", "type": "concept", "title": "English Poor Laws"}, {"id": "0d2bcaaa-6c46-4944-a9c6-716b0bcdec94", "type": "concept", "title": "Outdoor and indoor relief"}, {"id": "0c7c20dc-5656-4d00-8e5f-e7bf75b43b26", "type": "concept", "title": "Scientific charity"}, {"id": "7f9aa73c-c8d3-4463-b5bb-fdd36a387f40", "type": "concept", "title": "Settlement house movement"}], "description": "Early relief systems reveal enduring assumptions about morality, work, family, and public responsibility."}, {"id": "0993bf9e-7025-4673-8139-4471fbdaddd0", "type": "subtopic", "title": "New Deal and Great Society Foundations", "children": [{"id": "c53f696a-464f-409c-988a-37a64f20ffbf", "type": "concept", "title": "Social Security Act"}, {"id": "917cbab2-f050-47af-b5ce-0032ffc310cc", "type": "concept", "title": "Unemployment insurance"}, {"id": "b26ca226-d8a3-4a42-9f92-9c2be12de33f", "type": "concept", "title": "Medicare and Medicaid"}, {"id": "5a6daa0c-ff2e-4222-b4d0-d11314818d06", "type": "concept", "title": "War on Poverty programs"}], "description": "Major federal programs built the modern welfare state while also reflecting racial, gender, and labor exclusions."}, {"id": "fb29f96a-6de8-464c-96e2-8e859a531907", "type": "subtopic", "title": "Retrenchment, Devolution, and Contemporary Reform", "children": [{"id": "b87b9350-83b2-48fb-b5e1-8d730cd766d2", "type": "concept", "title": "Welfare reform of 1996"}, {"id": "76fc7f38-35dc-4777-80f6-8ba97788756b", "type": "concept", "title": "Block grants"}, {"id": "152862af-f4ac-4da7-bce2-ac589c446f55", "type": "concept", "title": "Privatization and contracting"}, {"id": "be517012-544c-4a6f-93ff-743da4162160", "type": "concept", "title": "Pandemic-era policy experiments"}], "description": "Recent history explains today's mix of federal, state, nonprofit, and market-based social provision."}]}, {"id": "2f5316a2-960e-4a83-99f3-3abbe8786a61", "type": "topic", "title": "The Welfare State, Ideology, and Political Values", "description": "Compare competing ideas about deservingness, markets, family, government, work, citizenship, and social rights.", "children": [{"id": "1a69f3ee-5893-4823-85af-26c6f470a37f", "type": "subtopic", "title": "Models of Welfare States", "children": [{"id": "0477116d-e8fb-4f01-9c28-7625653fbb71", "type": "concept", "title": "Liberal welfare regimes"}, {"id": "02971439-bb3d-4ae2-a2ef-4d8d329085bb", "type": "concept", "title": "Social democratic regimes"}, {"id": "2015a36b-8123-422b-8bf3-acc294ae0a1d", "type": "concept", "title": "Conservative or corporatist regimes"}, {"id": "80c0e371-b5fa-49a4-8306-3ffee2aa8e1a", "type": "concept", "title": "Family and market roles"}], "description": "Comparative models help students see U.S. social policy as one political design among many."}, {"id": "e71b1c3c-3c51-4a36-931b-e5fead444c23", "type": "subtopic", "title": "Ideologies of Poverty and Responsibility", "children": [{"id": "221ae777-03ad-4aa6-9b19-7f7bef144a90", "type": "concept", "title": "Individualism"}, {"id": "89a4e6f3-5b1a-456b-b40f-5fabad28a71b", "type": "concept", "title": "Structural explanations"}, {"id": "b1d58b3c-682c-4fb3-851c-4754dfda9371", "type": "concept", "title": "Deservingness narratives"}, {"id": "70861bbc-2366-4735-ae37-baf9633a74a9", "type": "concept", "title": "Work, dependency, and stigma"}], "description": "Policy design often encodes beliefs about who deserves support and why hardship happens."}, {"id": "f9f2352f-0287-4d7c-aa8a-85c10903027d", "type": "subtopic", "title": "Politics, Institutions, and Federalism", "children": [{"id": "f45ed82d-835e-4ece-8948-b17117b3f7ab", "type": "concept", "title": "Federal-state division"}, {"id": "47b30657-01ac-44f1-ab01-93db4980e0c5", "type": "concept", "title": "State waivers"}, {"id": "72d14648-5631-4cad-afce-c0714946bfa7", "type": "concept", "title": "Courts and rights"}, {"id": "aa629289-80f6-4c0e-91c5-8c9c0fae95bf", "type": "concept", "title": "Interest groups and advocacy"}], "description": "Social welfare policy is shaped by elections, courts, agencies, federalism, interest groups, and public opinion."}]}, {"id": "33ec385d-7dea-4c0b-87e1-58d62ffd634b", "type": "topic", "title": "Poverty, Inequality, and Economic Security", "description": "Understand poverty measurement, inequality trends, economic insecurity, and the policies designed to reduce hardship.", "children": [{"id": "42c131b3-7e10-43b3-b861-ac304314238c", "type": "subtopic", "title": "Measuring Poverty and Hardship", "children": [{"id": "8b2f316c-ddcb-48d2-b074-19944a7df859", "type": "concept", "title": "Official Poverty Measure"}, {"id": "fd78c367-1856-4c33-bfc9-168906a4add6", "type": "concept", "title": "Supplemental Poverty Measure"}, {"id": "9dd549ff-873b-41dd-8018-66e06656a80d", "type": "concept", "title": "Material hardship"}, {"id": "8c232190-06ce-4fc8-841a-a61b2e0bc8d4", "type": "concept", "title": "Asset poverty"}], "description": "Students need measurement literacy to interpret claims about need and policy impact."}, {"id": "2a6b6e54-11a1-44d3-91a4-6ce2060b4042", "type": "subtopic", "title": "Inequality and Mobility", "children": [{"id": "e97ccfe5-4985-49b8-96fe-4c940baf4e13", "type": "concept", "title": "Income inequality"}, {"id": "da3ff007-3986-477b-9971-f5bac426672d", "type": "concept", "title": "Wealth gaps"}, {"id": "6de97757-2d76-41d0-aaa7-0d4acddb8b8f", "type": "concept", "title": "Intergenerational mobility"}, {"id": "5761067c-ae11-4fd4-9248-851ce0a4b732", "type": "concept", "title": "Regional and racial disparities"}], "description": "Inequality shapes exposure to risk, access to opportunity, and demand for social services."}, {"id": "612ea51b-54b0-4b00-b357-b30d4fabe539", "type": "subtopic", "title": "Economic Security Policy Tools", "children": [{"id": "b3dfaaf0-05f9-4166-ac77-aff8b95edda6", "type": "concept", "title": "Cash transfers"}, {"id": "3a221947-4735-4ce3-bf40-cc10e7c10f4c", "type": "concept", "title": "Tax credits"}, {"id": "723a1d13-ca11-44b8-b4df-e3e1360194c5", "type": "concept", "title": "Minimum wage and labor standards"}, {"id": "18dbec66-0603-43ae-acc1-9c6510d33ec1", "type": "concept", "title": "Child allowances and family benefits"}], "description": "Students learn the major levers used to stabilize income and reduce hardship."}]}, {"id": "2329190d-0069-4057-b805-aa1f157f5fb8", "type": "topic", "title": "Major Social Welfare Programs and Service Systems", "description": "Map the core U.S. safety net and social insurance programs that structure everyday social work practice.", "children": [{"id": "e7f2cc55-603f-45b5-b423-0a6245dfb973", "type": "subtopic", "title": "Program Typologies", "children": [{"id": "72249d1d-f285-4921-8615-9b284bc79583", "type": "concept", "title": "Entitlements"}, {"id": "77454ea2-fa38-43ab-99e6-1561267b627f", "type": "concept", "title": "Means-tested programs"}, {"id": "34e1978e-5cce-4de8-b7ae-d0827ce3aefd", "type": "concept", "title": "Categorical programs"}, {"id": "1dffe776-9452-40e8-a05c-eaff5f3e13a4", "type": "concept", "title": "Discretionary services"}], "description": "A typology helps students organize a complex landscape of benefits, services, and financing structures."}, {"id": "d4ee9082-49a3-429b-b9ac-1ef7e8758899", "type": "subtopic", "title": "Eligibility and Access", "children": [{"id": "f47633a7-03a9-4592-abd1-b4d222832cea", "type": "concept", "title": "Income and asset tests"}, {"id": "9c58eb61-5211-4063-9721-65f5d1f8dfa1", "type": "concept", "title": "Categorical eligibility"}, {"id": "7c46edaf-7145-45c2-bbbf-16d20f42d177", "type": "concept", "title": "Immigration and residency rules"}, {"id": "fd169b6f-0256-4491-a4bb-f8497f12e749", "type": "concept", "title": "Documentation requirements"}], "description": "Eligibility rules translate policy values into lived access or exclusion."}, {"id": "bad0eec8-c566-4cf7-9ab7-cf71b8fcf973", "type": "subtopic", "title": "Service Delivery Systems", "children": [{"id": "7f27482a-cdd5-4931-b503-b836fbd76f5c", "type": "concept", "title": "Public human services agencies"}, {"id": "8bcac5c3-0722-494b-862f-58941870f5d1", "type": "concept", "title": "Nonprofit providers"}, {"id": "d0befbf6-1b92-4b17-8cc5-eff2c33b630d", "type": "concept", "title": "Managed care and contracting"}, {"id": "3aba2e7c-e951-4c01-8672-a6139f05793d", "type": "concept", "title": "Integrated service models"}], "description": "Students learn how services reach people through public agencies, nonprofits, contractors, and community organizations."}]}, {"id": "2870829d-72d0-4937-8d17-b5d24d30c375", "type": "topic", "title": "TANF, Welfare Reform, and Cash Assistance", "description": "Study cash assistance as a case of federalism, work requirements, stigma, race, gender, and administrative discretion.", "children": [{"id": "2bd7694b-e011-4c3d-a5b7-18b5d8aa9d73", "type": "subtopic", "title": "AFDC to TANF", "children": [{"id": "e3796b14-7423-4b57-957b-f0a65e89fee4", "type": "concept", "title": "AFDC history"}, {"id": "5a7b0c7c-39b6-48c4-a30b-ed7c79f073be", "type": "concept", "title": "Personal Responsibility and Work Opportunity Reconciliation Act"}, {"id": "5331a8b8-7bf9-476d-9e6d-7d3fda7d0757", "type": "concept", "title": "Block grants"}, {"id": "1ec9bf79-ff35-433e-a0ff-a66859eed9f2", "type": "concept", "title": "State flexibility"}], "description": "The transition from AFDC to TANF is a core case in welfare-state retrenchment, race, gender, and federalism."}, {"id": "19979af3-3d0a-4e5f-80c9-9347d76fc79b", "type": "subtopic", "title": "Work Requirements and Sanctions", "children": [{"id": "f7c23280-09d1-41ea-b59d-34d1d0012fc3", "type": "concept", "title": "Work participation rates"}, {"id": "056c1bea-5e8f-4d89-99ef-51d0f80b74d6", "type": "concept", "title": "Time limits"}, {"id": "85cec8e9-7c67-4373-ad6e-daaa36be89f9", "type": "concept", "title": "Sanctions"}, {"id": "5005ad33-d4a5-4632-90c5-892c766783f4", "type": "concept", "title": "Childcare and transportation barriers"}], "description": "TANF shows how behavior rules, surveillance, and sanctions shape access and family stability."}, {"id": "9986fd2f-5449-483d-b0b3-c1da24d82e63", "type": "subtopic", "title": "Contemporary Cash Policy Debates", "children": [{"id": "cf48686c-86ef-4270-8178-8673cb9b2daa", "type": "concept", "title": "Earned Income Tax Credit"}, {"id": "bba8566a-5f9a-425b-8de7-f14091ea513f", "type": "concept", "title": "Child Tax Credit"}, {"id": "0336ad29-d4f1-4342-9bc5-a72248b5e383", "type": "concept", "title": "Guaranteed income pilots"}, {"id": "d4a18059-b6c7-44e5-b76e-9e93e594d883", "type": "concept", "title": "Cash versus in-kind support"}], "description": "Students compare TANF with newer debates over unconditional cash, tax credits, and guaranteed income."}]}, {"id": "788168b3-9bca-46ca-86f2-48d5ac685803", "type": "topic", "title": "Social Security, SSI, Aging, and Disability Policy", "description": "Examine social insurance and disability benefits as foundations of economic security across the life course.", "children": [{"id": "42dd9302-be92-4276-9d90-46d684dc3541", "type": "subtopic", "title": "Social Security and Social Insurance", "children": [{"id": "798241a8-f3cd-499e-af8c-711a65ce778d", "type": "concept", "title": "Retirement benefits"}, {"id": "22df2d71-9667-4e0f-af2f-cdf6ed22f49e", "type": "concept", "title": "Survivor benefits"}, {"id": "75c64df2-5f69-4c96-8940-4b8ea07832e6", "type": "concept", "title": "Payroll taxes"}, {"id": "bcc01a5a-c78f-4fd4-8b06-b25776ba6a92", "type": "concept", "title": "Solvency debates"}], "description": "Social Security illustrates social insurance, intergenerational support, payroll financing, and old-age poverty reduction."}, {"id": "d0e08d79-aed4-4c82-9e16-a02d246f9aef", "type": "subtopic", "title": "SSI and Disability Benefits", "children": [{"id": "86f27091-2431-4273-8d5f-296119e2be91", "type": "concept", "title": "SSI eligibility"}, {"id": "5ee58b35-1aa7-4ac7-9c7e-0cba9ef28924", "type": "concept", "title": "SSDI basics"}, {"id": "c2742775-5344-4978-89c4-880ec93582d3", "type": "concept", "title": "Disability determination"}, {"id": "c7fcb28a-12a5-4249-8eed-ea91e74492e7", "type": "concept", "title": "Work incentives and benefit cliffs"}], "description": "SSI and disability policy show how definitions of disability, work, and need affect economic security."}, {"id": "23ebdea5-0f79-4576-9cd5-9c241ff22489", "type": "subtopic", "title": "Aging Services and Long-Term Care", "children": [{"id": "f706894a-6c62-4e34-a51a-f50c5ff8c57a", "type": "concept", "title": "Older Americans Act"}, {"id": "d01e89a9-2f4a-4a1c-9e27-f3978649a839", "type": "concept", "title": "Long-term services and supports"}, {"id": "8d4f14aa-775f-46c6-898b-fd8a11a805f3", "type": "concept", "title": "Home- and community-based services"}, {"id": "dd66bab8-d062-4452-ac27-6402f1e1852f", "type": "concept", "title": "Caregiving policy"}], "description": "Students connect demographic aging to care work, family burden, Medicaid, and community-based services."}]}, {"id": "b9ec26a5-c8bb-44f4-9b04-e3a02d0761ab", "type": "topic", "title": "Medicaid, Medicare, Health, and Mental Health Policy", "description": "Connect health coverage and behavioral health policy to access, equity, financing, and service delivery.", "children": [{"id": "08b57313-583f-4797-a551-48a1f35902a9", "type": "subtopic", "title": "Medicaid and Health Equity", "children": [{"id": "c50c509e-ad69-40d2-9552-8d948ba899a1", "type": "concept", "title": "Eligibility groups"}, {"id": "ceca4b24-b810-4c64-b435-a9574c0af29a", "type": "concept", "title": "Expansion and waivers"}, {"id": "277ed3a0-f0d2-43ff-9e59-fcde3af15a02", "type": "concept", "title": "Managed care"}, {"id": "f8b77279-14a2-4c82-9d39-49985732618e", "type": "concept", "title": "Long-term care financing"}], "description": "Medicaid is central to health access for low-income people and to many social service systems."}, {"id": "b129d674-388c-4b2a-91f7-02830aa769dd", "type": "subtopic", "title": "Medicare and Older Adult Health", "children": [{"id": "1b6b3bd7-df75-4ac4-aac8-b7a6e73441eb", "type": "concept", "title": "Parts A, B, C, and D"}, {"id": "63ce7a6d-6bd7-4677-bcb7-85c659dadb8a", "type": "concept", "title": "Premiums and cost-sharing"}, {"id": "7b5fc8c3-3364-485d-860c-19c84dd6740e", "type": "concept", "title": "Medigap and Medicare Advantage"}, {"id": "07c699de-79db-4d51-aecb-9b3d2518288d", "type": "concept", "title": "Dual eligible beneficiaries"}], "description": "Medicare demonstrates social insurance, coverage gaps, and the politics of aging policy."}, {"id": "b90dfda0-6298-4e30-819a-cb15cdce0963", "type": "subtopic", "title": "Mental Health and Behavioral Health Policy", "children": [{"id": "4f700773-ba92-418f-b52b-6186ba19a6f8", "type": "concept", "title": "Mental health parity"}, {"id": "3d48bb84-3b50-4d55-a841-f29ad2262976", "type": "concept", "title": "Substance use treatment"}, {"id": "1b7dcdf8-2e47-4b77-8c20-ea50f9b15075", "type": "concept", "title": "Community mental health"}, {"id": "d56ce29e-bc21-4ebf-8e6a-63ade2535f40", "type": "concept", "title": "988 and crisis systems"}], "description": "Behavioral health policy links coverage, parity, workforce, crisis care, and community-based supports."}]}, {"id": "63d79c0a-140c-479e-a3af-68cd50dd2815", "type": "topic", "title": "SNAP, Food Assistance, and Basic Needs Policy", "description": "Analyze food assistance and basic-needs supports as anti-poverty, health, and dignity policies.", "children": [{"id": "fee7e022-2b48-4e29-aa50-f06117d1f543", "type": "subtopic", "title": "SNAP Design and Access", "children": [{"id": "fd553b3c-2cac-400b-bed1-408c31b1c41b", "type": "concept", "title": "Eligibility and benefit levels"}, {"id": "e5956131-8176-4b27-b166-72c5695ce478", "type": "concept", "title": "Electronic benefit transfer"}, {"id": "3408392b-e115-4987-8a22-f0b6ec5316ae", "type": "concept", "title": "Recertification"}, {"id": "70be47a2-3b67-46a0-91ce-72a48b4a107a", "type": "concept", "title": "Work rules and exemptions"}], "description": "SNAP illustrates nutrition policy, anti-poverty policy, administrative access, and stigma."}, {"id": "b5ce0991-7b4d-4bf2-b048-50ad7f9fd38d", "type": "subtopic", "title": "Food Security and Public Health", "children": [{"id": "6d4ba3fb-3ed5-4229-97a7-143ecdf18487", "type": "concept", "title": "Food insecurity"}, {"id": "5f428636-203a-4d90-ac40-fd597f04fded", "type": "concept", "title": "Food deserts and food apartheid"}, {"id": "f5a82be7-f193-46bf-8199-c2ec45461d4f", "type": "concept", "title": "School meals"}, {"id": "6d8b59a9-fc13-40d4-b28d-cbad30716b8d", "type": "concept", "title": "WIC"}], "description": "Food policy connects income, neighborhood access, health outcomes, and family stress."}, {"id": "0a25d558-f7c2-4161-a6d4-a28bb33b2f35", "type": "subtopic", "title": "Emergency and Community Food Systems", "children": [{"id": "e1bd3c77-dab8-4441-af7b-d438ad15608a", "type": "concept", "title": "Food banks"}, {"id": "dad8fb8f-ac4d-4403-b08a-42660f26f370", "type": "concept", "title": "Mutual aid"}, {"id": "cea3a39e-4f92-4fdd-9341-3896b34a0752", "type": "concept", "title": "Disaster nutrition supports"}, {"id": "91bfe369-6a63-464e-b690-68b5bde9abf4", "type": "concept", "title": "Local food policy councils"}], "description": "Students examine how public benefits interact with charitable and community-based food systems."}]}, {"id": "21089e58-039b-4b68-8555-722b8e65ab5c", "type": "topic", "title": "Housing Policy, Homelessness, and Place-Based Inequality", "description": "Study housing assistance, homelessness, segregation, eviction, and neighborhood opportunity as central welfare issues.", "children": [{"id": "7fdd45c4-fd99-42ce-a0d1-88225b05a8d1", "type": "subtopic", "title": "Housing Assistance Programs", "children": [{"id": "517644ad-184a-4942-86be-49dc5cc4fe47", "type": "concept", "title": "Public housing"}, {"id": "4966f477-69cb-4fee-89a6-9f2bdd8e1be7", "type": "concept", "title": "Housing Choice Vouchers"}, {"id": "3ecc1843-ad58-4f0b-9271-a4c97198a64b", "type": "concept", "title": "Project-based rental assistance"}, {"id": "a3f09e1d-f180-4877-99d8-b7f1ac0395b0", "type": "concept", "title": "Low-Income Housing Tax Credit"}], "description": "Housing policy is a central anti-poverty and family-stability issue."}, {"id": "bff6c9d7-ecee-4022-bf74-c3d8a5be574f", "type": "subtopic", "title": "Homelessness Policy and Services", "children": [{"id": "5676a6a3-16f7-46e6-bba4-4a4172b831f4", "type": "concept", "title": "Continuums of Care"}, {"id": "4e65f366-92c1-48b3-aee8-96fbc75d1c74", "type": "concept", "title": "Housing First"}, {"id": "e200f281-597a-4f85-bd3b-750e9c86b0d7", "type": "concept", "title": "Shelter systems"}, {"id": "41378517-1bca-441d-98a4-dd0c377d45b1", "type": "concept", "title": "Permanent supportive housing"}], "description": "Students learn how homelessness policy blends housing, health, behavioral health, and local service systems."}, {"id": "5865fefe-4089-4b64-aeef-6d5f0acf712b", "type": "subtopic", "title": "Segregation, Eviction, and Neighborhood Opportunity", "children": [{"id": "8aa46177-f0ad-4c8a-a2a0-f3ac6a393e77", "type": "concept", "title": "Redlining and exclusionary zoning"}, {"id": "49435483-064b-4f65-aa07-7dabb100a37b", "type": "concept", "title": "Eviction"}, {"id": "ef7fea1c-8f20-4dda-baa6-8137c294c47d", "type": "concept", "title": "Fair housing"}, {"id": "2847b8c2-82fe-4128-b843-c3507db1fab5", "type": "concept", "title": "Opportunity mapping"}], "description": "Housing policy has shaped racial wealth gaps, school access, exposure to harm, and social mobility."}]}, {"id": "d495c54a-58cf-4837-9d5e-1996223667ca", "type": "topic", "title": "Child Welfare, Families, and Care Policy", "description": "Understand child welfare policy in relation to family support, poverty, safety, surveillance, race, and community resources.", "children": [{"id": "1d83421c-3561-429b-9ac6-4d819be0acd9", "type": "subtopic", "title": "Child Welfare System Basics", "children": [{"id": "518bfdaf-eaf5-40cd-8b0d-350b809013ea", "type": "concept", "title": "Mandated reporting"}, {"id": "da14b2ca-92c2-4a32-80c2-a4988f48a932", "type": "concept", "title": "Investigation and substantiation"}, {"id": "77c31e2c-6b9c-4690-b1cc-9d916eed637a", "type": "concept", "title": "Foster care"}, {"id": "8b8a477a-ad37-4576-a121-ed739f897a11", "type": "concept", "title": "Reunification, guardianship, and adoption"}], "description": "Students learn the structure and goals of child protective services, foster care, prevention, and permanency."}, {"id": "275de94c-da44-46d3-a13f-ccda68898e3b", "type": "subtopic", "title": "Family Support and Prevention", "children": [{"id": "9fe8bfaa-bf37-4c63-85cc-26f07143a0b5", "type": "concept", "title": "Family preservation"}, {"id": "bf0f9095-be6e-4fb5-9bba-7d5415d21d94", "type": "concept", "title": "Concrete supports"}, {"id": "8284aea2-6d49-4d44-93ba-ab091bb967e9", "type": "concept", "title": "Childcare policy"}, {"id": "2a18f62c-7df1-484d-ae6f-58b8088aedd7", "type": "concept", "title": "Paid leave and family policy"}], "description": "A world-class policy view includes economic supports and prevention, not only investigations after harm."}, {"id": "e1678444-115f-4a9b-b675-d260e32a5e09", "type": "subtopic", "title": "Equity and Surveillance", "children": [{"id": "5dcda740-2e45-4fef-af78-32ca2ef5fa45", "type": "concept", "title": "Disproportionality"}, {"id": "9dd9ef33-4690-4539-8a1c-48d6a418db53", "type": "concept", "title": "Neglect and poverty"}, {"id": "5574460a-184e-4aa3-8b6d-c3cc16040889", "type": "concept", "title": "Kinship care"}, {"id": "4efe633c-87c2-4d62-950b-48bcf67bc4fe", "type": "concept", "title": "Community-based alternatives"}], "description": "Child welfare policy raises difficult questions about poverty, race, risk, coercion, and family autonomy."}]}, {"id": "63ed14f2-a90f-4389-a2d0-d8f72a9321eb", "type": "topic", "title": "Policy Analysis Frameworks for Undergraduates", "description": "Develop a usable toolkit for comparing policy options by goals, evidence, equity, cost, feasibility, and implementation.", "children": [{"id": "53316ad8-aa86-4072-b350-9540f2c88a46", "type": "subtopic", "title": "Problem Definition and Goals", "children": [{"id": "cd1710aa-a662-436e-8fd9-f532a30a02fe", "type": "concept", "title": "Problem statements"}, {"id": "b6a9a89c-1913-472f-aba0-b09406a08551", "type": "concept", "title": "Affected populations"}, {"id": "70e215cd-7a76-4d04-8f34-85bfcb6ce808", "type": "concept", "title": "Root causes"}, {"id": "126d5cb7-0efc-4e66-992b-d23d4a05d6a8", "type": "concept", "title": "Policy goals and objectives"}], "description": "Before analyzing solutions, students must learn to define the policy problem and name goals clearly."}, {"id": "f8b44b4d-2d14-47db-b26e-fa0f63399cae", "type": "subtopic", "title": "Comparing Alternatives", "children": [{"id": "b3f1aca8-5b0b-44b9-aabd-67335ea352ee", "type": "concept", "title": "Status quo baseline"}, {"id": "88c1c8ae-02ff-4f9d-b8f3-30b1bf4919bf", "type": "concept", "title": "Policy alternatives"}, {"id": "61de20e2-ae16-477f-aab7-14b64c5f83d3", "type": "concept", "title": "Criteria matrices"}, {"id": "3564a351-d5c7-431a-b409-c0546c22fde9", "type": "concept", "title": "Tradeoffs and uncertainty"}], "description": "Students practice comparing options rather than treating policy opinions as self-evident."}, {"id": "54e4e28d-d65e-48fb-bba0-418f705448ee", "type": "subtopic", "title": "Recommendation Writing", "children": [{"id": "a5459310-89cb-4764-990c-4a57eabb96e0", "type": "concept", "title": "Executive summaries"}, {"id": "f97c3321-1f96-4a9b-bb2c-9617908fd3b3", "type": "concept", "title": "Evidence and citations"}, {"id": "1a1b20e3-47c0-46bb-aba6-8d811b06bb4c", "type": "concept", "title": "Feasibility"}, {"id": "e09a12ee-df9e-415a-b1a8-acb6f80422d7", "type": "concept", "title": "Implementation risks"}], "description": "Undergraduates learn to make concise, evidence-based recommendations for realistic audiences."}]}, {"id": "8c2f2e58-1bc0-4c6e-9897-9e1a8119a963", "type": "topic", "title": "Equity, Race, Gender, Disability, Immigration, and Intersectionality", "description": "Evaluate how social welfare policy distributes benefit, burden, access, stigma, and power across social groups.", "children": [{"id": "02001951-99d7-4765-9ab9-301119f0d478", "type": "subtopic", "title": "Equity Impact Analysis", "children": [{"id": "833841e7-cccd-46d6-b7f1-a192fe2287a2", "type": "concept", "title": "Distributional effects"}, {"id": "ab2bdf8d-70e9-4f02-806c-a8a931d21466", "type": "concept", "title": "Disaggregated data"}, {"id": "ee3d9eb4-9d25-42dc-b4c3-ca5ea62bfdd3", "type": "concept", "title": "Equity impact statements"}, {"id": "d3dde1ec-27a7-4cc3-898c-65b7c8df2744", "type": "concept", "title": "Community-defined outcomes"}], "description": "Equity analysis asks who benefits, who bears burdens, and whose voice shaped the design."}, {"id": "462425c5-4c44-46da-8912-6e5a1197a4b0", "type": "subtopic", "title": "Race, Gender, Disability, and Immigration", "children": [{"id": "75838a52-b742-4dec-bed3-30fa035aeb30", "type": "concept", "title": "Structural racism"}, {"id": "f9528653-5092-498b-8389-7138a8252954", "type": "concept", "title": "Gendered care work"}, {"id": "10390879-9904-452e-ac1d-f6baf6e66a4d", "type": "concept", "title": "Ableism and disability access"}, {"id": "bb0b2e90-4738-43c5-990c-a8d91cdefae1", "type": "concept", "title": "Immigration status and public charge concerns"}], "description": "Social welfare programs often sort access and stigma through identity, family structure, work, citizenship, and disability."}, {"id": "8bf57897-96d1-4040-bd7a-be8bcd67a816", "type": "subtopic", "title": "Administrative Burden and Access", "children": [{"id": "6f2f8e16-4407-40fb-82bc-417be65d5836", "type": "concept", "title": "Learning costs"}, {"id": "76073192-f7de-4c22-98bf-0971ab9cd2b3", "type": "concept", "title": "Compliance costs"}, {"id": "fa8e239d-bea1-47d1-935e-e126d3736946", "type": "concept", "title": "Psychological costs"}, {"id": "b202eae2-8d23-4e9c-812a-b260fea0fd28", "type": "concept", "title": "Burden reduction strategies"}], "description": "Even generous programs fail when paperwork, stigma, time, digital barriers, or discretion block access."}]}, {"id": "4adcd406-4830-4e2e-b026-8a8323660b48", "type": "topic", "title": "Policy-Practice Connection and Advocacy", "description": "Show how direct practice, agency work, community organizing, and policy advocacy inform one another.", "children": [{"id": "6299e832-1948-402e-a92a-680892d4b199", "type": "subtopic", "title": "How Practice Reveals Policy", "children": [{"id": "9c94aec7-47bd-489c-a7bf-889dc36f92de", "type": "concept", "title": "Eligibility denials"}, {"id": "f9f7bb95-6c98-4d2b-9425-c420f60bdfc9", "type": "concept", "title": "Service gaps"}, {"id": "462d65a0-a36d-4fde-8942-bc365c96f853", "type": "concept", "title": "Benefit cliffs"}, {"id": "06898f7f-3109-411c-9d46-37438652ab10", "type": "concept", "title": "Frontline discretion"}], "description": "Direct-service encounters can show where policy design breaks down in real life."}, {"id": "c0bae04b-8d86-4ad9-b57c-100ffd3989b9", "type": "subtopic", "title": "Policy Advocacy Skills", "children": [{"id": "cd4587d4-0822-4d61-bb1c-6919b89edaf4", "type": "concept", "title": "Legislative visits"}, {"id": "bfddced4-559f-489d-8c00-063eef948419", "type": "concept", "title": "Public comments"}, {"id": "9656ee24-8c26-4fec-82d8-aefb78a66e40", "type": "concept", "title": "Testimony"}, {"id": "3865968f-3fdc-46b1-8c50-2b073e951599", "type": "concept", "title": "Policy briefs"}], "description": "Students learn entry-level skills for connecting evidence, stories, and professional ethics to public decisions."}, {"id": "6d1cf0a0-ca7b-4100-846b-a7bb0ab67101", "type": "subtopic", "title": "Community and Coalition Advocacy", "children": [{"id": "1d5512a2-f043-46cf-8df3-912638d64514", "type": "concept", "title": "Coalition building"}, {"id": "e23106ab-dcc1-4ea2-a17f-e4037c42b833", "type": "concept", "title": "Community organizing"}, {"id": "b0505562-cd91-41af-a31c-0a2c5086a196", "type": "concept", "title": "Power mapping"}, {"id": "b5403c64-b714-4211-bddc-c7748914a207", "type": "concept", "title": "Participatory agenda setting"}], "description": "Policy change is stronger when affected communities shape goals and strategy."}]}, {"id": "37d3b084-8a79-4741-bbf5-bbe3289ef73b", "type": "topic", "title": "Program Design, Implementation, Administrative Burden, and Evaluation", "description": "Move from policy intent to actual service experience, frontline practice, outcomes, and accountability.", "children": [{"id": "830eddc6-3fb9-4f01-be62-584fc1f1831f", "type": "subtopic", "title": "Program Design and Implementation", "children": [{"id": "c7d018e2-55f1-471f-953d-a8a859a9d412", "type": "concept", "title": "Implementation chains"}, {"id": "3f1387b7-bc88-46d7-b109-d615a83e683a", "type": "concept", "title": "Program rules"}, {"id": "aa4883f0-2511-49cd-b0f7-d509985289fd", "type": "concept", "title": "Workforce capacity"}, {"id": "86819ccd-bf0e-4806-b6c3-197c02ea8924", "type": "concept", "title": "Contracting and nonprofit delivery"}], "description": "Policy intent only matters if programs can actually deliver benefits and services."}, {"id": "8d037d59-2855-46e0-ba23-7762b9b21dfa", "type": "subtopic", "title": "Frontline Administration", "children": [{"id": "ae9e01a0-3ac8-4c8e-9447-02aabca755d3", "type": "concept", "title": "Street-level bureaucracy"}, {"id": "742981a4-4e88-47b2-9f65-788615e7d27c", "type": "concept", "title": "Discretion"}, {"id": "6217c4fd-966c-4111-b363-d06720b2f71b", "type": "concept", "title": "Supervision and accountability"}, {"id": "9c07feec-0bbe-4932-9436-ead49dd07233", "type": "concept", "title": "Client experience"}], "description": "Students examine how caseworkers, agencies, and contractors translate rules into everyday decisions."}, {"id": "20373abf-1e97-4f32-a27a-9ab75841d758", "type": "subtopic", "title": "Evaluation and Learning", "children": [{"id": "f9bb4e7b-35bc-4625-a8f8-dfe5e1f21e79", "type": "concept", "title": "Logic models"}, {"id": "ef2925e7-ab3d-4e76-bda5-a0d0f773083d", "type": "concept", "title": "Process evaluation"}, {"id": "746449a2-8bd3-47a5-b4d0-6b83c31e6716", "type": "concept", "title": "Outcome evaluation"}, {"id": "625988d5-9018-49b5-87e2-ac59b1ca8f4d", "type": "concept", "title": "Continuous quality improvement"}], "description": "Evaluation helps determine whether social welfare programs improve access, dignity, equity, and outcomes."}]}, {"id": "27a4d469-6c4f-4c20-9554-b8d217f77c5d", "type": "topic", "title": "Capstone: Social Welfare Policy Analysis Project", "description": "Synthesize course learning through a policy brief, program map, equity analysis, and practice-informed recommendation.", "children": [{"id": "4a862b0f-fb9a-41bb-bc1b-441c578439ee", "type": "subtopic", "title": "Policy Area Profile", "children": [{"id": "9d984942-3144-4563-b1ca-73357ab91e50", "type": "concept", "title": "Program history"}, {"id": "50e5d0b8-dd14-4cc4-ae19-a38f411a9520", "type": "concept", "title": "Eligibility and financing"}, {"id": "51fcff13-6f71-48ed-ab10-c1ebbeb7f556", "type": "concept", "title": "Affected populations"}, {"id": "baf23631-fb0f-42bc-96bc-d37e28faf01c", "type": "concept", "title": "Current debates"}], "description": "Students demonstrate command of one social welfare policy area and its institutional context."}, {"id": "9e333523-2145-49d3-b064-f11af408b106", "type": "subtopic", "title": "Equity and Service Access Analysis", "children": [{"id": "f998670f-ffe2-486e-a698-d588e7649c8a", "type": "concept", "title": "Data scan"}, {"id": "63ab6f7e-7b62-47d9-9cc1-d3dea604b6d2", "type": "concept", "title": "Stakeholder perspectives"}, {"id": "f63711a3-e340-44cd-b811-86e97e4a1701", "type": "concept", "title": "Burden map"}, {"id": "5cf929a9-cdfc-4190-9fa2-4c48dd1ce311", "type": "concept", "title": "Equity implications"}], "description": "Students identify access barriers, disparities, administrative burdens, and service-delivery gaps."}, {"id": "8c936396-e41b-4188-ba50-65f705a6985b", "type": "subtopic", "title": "Policy Brief and Recommendation", "children": [{"id": "a4357c86-0cab-4269-b796-f4fcfb2d888f", "type": "concept", "title": "Problem statement"}, {"id": "855d4823-56f6-4cc6-9944-eac623625cde", "type": "concept", "title": "Options and criteria"}, {"id": "00a8efe7-03cd-4e72-bf35-f7634bb233c5", "type": "concept", "title": "Recommendation"}, {"id": "d5c71f76-1b2d-43e1-b73a-6ca8b859f6b3", "type": "concept", "title": "Implementation and evaluation plan"}], "description": "The capstone asks students to translate analysis into a clear, evidence-grounded recommendation."}]}], "dbBacked": true}$swpsjson$::jsonb,
